// Generated by clock-gallery/tools/lazy.mjs from oled-clock/sim/js/player.js: do not edit.
// Deterministic driver: "design X at animation time t" -> a controller in the
// state firmware would leave it in, plus the picture the glass shows.
//
// Every frame is built the same way:
//   1. power up the controller and run the module's init sequence (free)
//   2. replay the previous frame (t - 1/fps) uncosted, so RAM and registers
//      hold what the last frame left there
//   3. build this frame with the bus meter running: the design draws into a
//      1-bit canvas, the driver sends it, and the design's register requests
//      (contrast, invert, start line, scroll) go out only where they change
// Step 2 is what makes the dirty-rectangle driver's cost and the tearing
// model honest, without the design keeping any state of its own.

import { OLED, BUSES } from '../../skills/oled-clock/sim/js/ssd1306.js';
import { initSequence, flush } from '../../skills/oled-clock/sim/js/driver.js';
import { MODULES } from '../../skills/oled-clock/sim/js/modules.js';
import { drawPanel, canvasSize } from '../../skills/oled-clock/sim/js/panel.js';
import * as kit from '../../skills/oled-clock/sim/js/kit.js';
const DESIGNS = {};   // filled one design at a time by faces/load.js

export { DESIGNS, MODULES };

/** Fixed date renders are anchored to, so they are reproducible. */
const BASE_DATE = new Date(2026, 9, 2); // 2 Oct 2026, local time

/** Wall clock at animation time t, given the clock shown at t = 0. */
export function dateFor(clock, t = 0) {
  const [h = 10, m = 9, s = 30] = String(clock).split(':').map(Number);
  const d = new Date(BASE_DATE);
  d.setHours(h, m, Math.floor(s), Math.round((s % 1) * 1000));  // seconds may carry a fraction
  return new Date(d.getTime() + t * 1000);
}

/**
 * The module a design runs on, with any override. On an SPI bus the board is
 * the module's SPI version (same glass, 7-pin header), where it has one.
 */
export function moduleOf(design, override, bus) {
  const key = override ?? design.module ?? '096-128x64';
  const mod = MODULES[key];
  if (!mod) throw new Error(`unknown module '${key}' (have: ${Object.keys(MODULES).join(', ')})`);
  const spi = BUSES[bus ?? design.bus]?.kind === 'spi' && mod.spi;
  return spi ? { key, ...mod, label: spi.label, pcb: { ...mod.pcb, header: spi.header } } : { key, ...mod };
}

/** Frames per second a design is sent at: the override if given, else its own. */
export function fpsOf(design, override) {
  const f = Number(override ?? design?.fps ?? 20);
  return Number.isFinite(f) && f > 0 ? f : 20;
}

/**
 * Register requests a design can make from `ctx.oled`. Each is the state the
 * design wants for this frame; the player turns differences from the
 * controller's current state into commands.
 */
function makeControls() {
  const want = {};
  return {
    want,
    /** Global brightness, 0..255 (0x81). Changes segment current, not pixels. */
    contrast(v) { want.contrast = Math.max(0, Math.min(255, Math.round(v))); return this; },
    /** Inverse display (0xA7): lit and unlit swap, for free. */
    invert(on = true) { want.inverse = !!on; return this; },
    /** Display start line (0x40-0x7F): which RAM row is shown at the top. Rolls the picture vertically for one byte. */
    startLine(n) { want.startLine = ((Math.round(n) % 64) + 64) % 64; return this; },
    /** Display offset (0xD3): moves the picture up by n rows on the COMs. */
    offset(n) { want.offset = ((Math.round(n) % 64) + 64) % 64; return this; },
    /** Panel on or off (0xAF/0xAE). Off is black, RAM kept. */
    display(on = true) { want.displayOn = !!on; return this; },
    /** All pixels lit regardless of RAM (0xA5). */
    allOn(on = true) { want.entireOn = !!on; return this; },
    /**
     * Continuous horizontal hardware scroll (0x26/0x27 + 0x2F) of pages
     * startPage..endPage, one pixel every `interval` panel frames
     * (2, 3, 4, 5, 25, 64, 128 or 256). `since` is how long it has been
     * running, in seconds: derive it from the clock. While it runs the
     * driver sends no RAM (the datasheet forbids writing during a scroll),
     * so the design must keep drawing the picture it started with.
     */
    scroll({ dir = 1, startPage = 0, endPage = 7, interval = 5, since = 0 }) {
      want.scroll = { dir, startPage, endPage, interval, since };
      return this;
    },
  };
}

const INTERVAL_CODE = { 5: 0, 64: 1, 128: 2, 256: 3, 3: 4, 4: 5, 25: 6, 2: 7 };

/** Run the design once and push it into `oled`. */
function runFrame(oled, design, mod, { t, date, fps, night = 'auto' }) {
  const g = new kit.Gfx(mod.cols, (design.ramPages ?? mod.rows / 8) * 8);
  const controls = makeControls();
  const ctx = {
    t, date, fields: kit.clockFields(date), kit, fps,
    night: kit.nightLevel(date, night),
    W: mod.cols, H: mod.rows, module: mod, oled: controls,
  };
  design.frame(g, ctx);
  // A register the design did not ask for this frame goes back to what the
  // module's init left it at. So each frame fully defines the registers as
  // well as the pixels, and a frame that follows another (the live view)
  // looks exactly like one built on its own (stills, check.mjs).
  const want = { ...initRegisters(mod), ...controls.want };
  const r = oled.r;

  // A running scroll that should stop, stops before RAM is touched.
  const scrolling = !!want.scroll;
  if (r.scrollOn && (!scrolling || !sameScroll(r.scroll, want.scroll))) oled.commands(0x2e);

  // RAM: not while a scroll keeps running.
  // After a scroll is stopped the RAM must be rewritten in full (S11 p29).
  const keepScrolling = scrolling && r.scrollOn;
  if (!keepScrolling) {
    flush(oled, g.toPages(), {
      width: mod.cols, firstPage: 0, pageCount: g.height / 8, colOffset: mod.colOffset ?? 0,
      mode: oled.ramStale ? 'full' : design.driver ?? 'full',
    });
    oled.ramStale = false;
  }

  const cmds = [];
  if (want.contrast !== undefined && want.contrast !== r.contrast) cmds.push(0x81, want.contrast);
  if (want.inverse !== undefined && want.inverse !== r.inverse) cmds.push(want.inverse ? 0xa7 : 0xa6);
  if (want.entireOn !== undefined && want.entireOn !== r.entireOn) cmds.push(want.entireOn ? 0xa5 : 0xa4);
  if (want.startLine !== undefined && want.startLine !== r.startLine) cmds.push(0x40 | want.startLine);
  if (want.offset !== undefined && want.offset !== r.offset) cmds.push(0xd3, want.offset);
  if (want.displayOn !== undefined && want.displayOn !== r.displayOn) cmds.push(want.displayOn ? 0xaf : 0xae);
  if (cmds.length) oled.commands(cmds);

  if (scrolling && !keepScrolling) {
    const s = want.scroll;
    const code = INTERVAL_CODE[s.interval];
    if (code === undefined) throw new Error(`scroll interval ${s.interval} is not one the chip has (2, 3, 4, 5, 25, 64, 128, 256)`);
    oled.commands(s.dir > 0 ? 0x26 : 0x27, 0x00, s.startPage, code, s.endPage, 0x00, 0xff, 0x2f);
  }
  oled.scrollSince = scrolling ? want.scroll.since : 0;
  return { g, want };
}

/** Register values right after the module's init sequence, cached per module. */
const INIT_REGS = new Map();
function initRegisters(mod) {
  const key = `${mod.key}/${mod.chip}/${mod.rows}`;
  if (!INIT_REGS.has(key)) {
    const ref = new OLED({ chip: mod.chip });
    ref.commands(initSequence(mod.chip, mod.rows));
    const { contrast, inverse, entireOn, startLine, offset, displayOn } = ref.r;
    INIT_REGS.set(key, { contrast, inverse, entireOn, startLine, offset, displayOn });
  }
  return INIT_REGS.get(key);
}

function sameScroll(a, b) {
  return a && b && a.dir === b.dir && a.startPage === b.startPage && a.endPage === b.endPage && a.interval === b.interval;
}

/**
 * Build the controller state for design `name` at time `t`.
 *
 * `opts.night` is the night-dimming mode designs see as `ctx.night`: 'auto'
 * (default, by the clock, as the hardware would), 'off' or 'on'.
 * `opts.fps` overrides the design's frame rate. `opts.prev` continues from a
 * controller a previous call returned, as firmware does from one frame to
 * the next: much cheaper than priming, and what the live view uses. It is
 * ignored if it belongs to another chip or bus.
 * @param {object} [opts] { t, clock, date, bus, module, fps, night, prime, prev }
 */
export function buildFrame(name, opts = {}) {
  const design = DESIGNS[name];
  if (!design) throw new Error(`unknown design '${name}' (have: ${Object.keys(DESIGNS).join(', ')})`);
  const bus = opts.bus ?? design.bus ?? 'i2c400';
  const mod = moduleOf(design, opts.module, bus);
  const fps = fpsOf(design, opts.fps);
  const t = opts.t ?? 0;
  const clock = opts.clock ?? '10:09:30';
  const at = (tt) => opts.date ? new Date(opts.date.getTime() + (tt - t) * 1000) : dateFor(clock, tt);

  let oled = opts.prev;
  if (!oled || oled.chip !== mod.chip || oled.bus !== bus) {
    oled = new OLED({ chip: mod.chip, bus });
    oled.commands(initSequence(mod.chip, mod.rows));
    if (opts.prime !== false) runFrame(oled, design, mod, { t: t - 1 / fps, date: at(t - 1 / fps), fps, night: opts.night });
  }
  oled.beginFrame();
  const { g } = runFrame(oled, design, mod, { t, date: at(t), fps, night: opts.night });
  return { oled, design, module: mod, fps, report: oled.report(), canvas: g, date: at(t) };
}

/**
 * Brightness of every physical pixel, 0..1 linear light, row-major.
 *
 * `tear`: show one panel refresh as it is scanned while this frame is still
 * on the wire, instead of the settled frame. `t` is the instant (seconds),
 * `frameStart` when this frame's bytes began to go out.
 */
export function scanout(oled, mod, { tear = false, t = 0, frameStart = 0 } = {}) {
  const W = mod.cols, H = mod.rows;
  const out = new Float32Array(W * H);
  const wiring = panelWiring(oled, mod);
  const finalRegs = oled.r;
  const period = 1 / oled.frameRate(finalRegs);

  for (let y = 0; y < H; y++) {
    let r = finalRegs, sinceUs = Infinity;
    if (tear) {
      // When was this row last scanned? Rows go out in row-counter order.
      const k0 = rowCounterForPhysical(oled, wiring, y, finalRegs);
      const slot = (Math.max(0, k0) / finalRegs.mux) * period;
      const scanned = Math.floor((t - slot) / period) * period + slot;
      sinceUs = (scanned - frameStart) * 1e6;
      r = regsAt(oled, sinceUs);
    }
    const k = rowCounterForPhysical(oled, wiring, y, r);
    const lum = !r.displayOn || (mod.chargePump && !r.chargePump) ? 0 : brightness(r.contrast);
    for (let x = 0; x < W; x++) {
      let on;
      if (r.entireOn) on = 1;
      else if (k < 0) on = 0;
      else {
        const ramRow = (r.startLine + k) % 64;
        let sx = x;
        if (r.scrollOn && r.scroll && ramRow >> 3 >= r.scroll.startPage && ramRow >> 3 <= r.scroll.endPage) {
          // The scrolled pages rotate as a ring: what leaves one edge comes
          // back at the other. Direction is as the viewer sees it with the
          // standard (remapped) init.
          const steps = Math.floor((oled.scrollSince * oled.frameRate(r)) / r.scroll.interval);
          sx = (((x - r.scroll.dir * steps) % W) + W) % W;
        }
        on = ramBit(oled, wiring.seg[sx], ramRow, tear ? sinceUs : Infinity);
        if (r.inverse) on ^= 1;
      }
      out[y * W + x] = on * lum;
    }
  }
  return out;
}

/** A RAM bit as the panel would read it `sinceUs` into the frame. */
function ramBit(oled, seg, row, sinceUs) {
  const i = (row >> 3) * oled.ramCols + seg;
  const landed = oled.writeAt[i];
  const byte = sinceUs === Infinity || (landed >= 0 && landed <= sinceUs) ? oled.ram[i] : oled.ramBefore[i];
  return (byte >> (row & 7)) & 1;
}

/** Registers as they stood `us` microseconds into the frame. */
function regsAt(oled, us) {
  let r = oled.regLog[0]?.r ?? oled.r;
  for (const e of oled.regLog) if (e.at <= us) r = e.r;
  return r;
}

/**
 * How the module's glass is wired to the chip: for each physical column the
 * SEG output, for each physical row the COM pin. Derived from the init the
 * panel was designed for, so that init shows RAM upright; any other
 * configuration is then simulated through the same wiring.
 */
const WIRING = new Map();
export function panelWiring(oled, mod) {
  const key = `${mod.key}/${oled.chip}`;
  if (!WIRING.has(key)) WIRING.set(key, deriveWiring(oled, mod));
  return WIRING.get(key);
}

function deriveWiring(oled, mod) {
  const ref = new OLED({ chip: mod.chip });
  ref.commands(initSequence(mod.chip, mod.rows));
  const intended = ref.r;
  const seg = new Int16Array(mod.cols);
  // The SEG that the standard init stores canvas column x at is the one
  // wired to physical column x.
  for (let x = 0; x < mod.cols; x++) seg[x] = ref.segOf(x + (mod.colOffset ?? 0), intended);
  const pin = new Int16Array(mod.rows);
  for (let y = 0; y < mod.rows; y++) {
    for (let com = 0; com < 64; com++)
      if (oled.rowCounterOf(com, intended) === y) { pin[y] = oled.pinOf(com, intended); break; }
  }
  return { seg, pin };
}

/** Row counter value shown on physical row y under registers r, or -1 if dark. */
function rowCounterForPhysical(oled, wiring, y, r) {
  const pin = wiring.pin[y];
  for (let com = 0; com < 64; com++) if (oled.pinOf(com, r) === pin) return oled.rowCounterOf(com, r);
  return -1;
}

/**
 * Light output for a contrast setting, relative to 0xFF. Segment current is
 * linear in the setting (S11 §8.8: ISEG = contrast/256 x IREF x 8; measured
 * 25 / 69 / 100 µA at 3F / AF / FF). That luminance follows current is an
 * assumption. The formula reaches zero at 00h; the +1 keeps the simulated
 * panel faintly lit there, which is unverified.
 */
export function brightness(contrast) {
  return (contrast + 1) / 256;
}

/**
 * Build a frame and paint it.
 * @param {HTMLCanvasElement} canvas
 */
export function renderToCanvas(canvas, name, opts = {}) {
  const { colour, scale, px = 6, style = 'photo', crop = 'view', tear = false, ...rest } = opts;
  const design = DESIGNS[name];
  const fps = fpsOf(design, rest.fps);
  const t = rest.t ?? 0;
  const k = Math.floor(t * fps + 1e-9);
  // The controller holds the last frame sent at or before t.
  const built = buildFrame(name, { ...rest, t: k / fps });
  const mod = built.module;
  const levels = scanout(built.oled, mod, { tear, t, frameStart: k / fps });
  const sc = scale ?? px / mod.pitch.x;
  const size = paint(canvas, mod, levels, { colour: colour ?? design.colour ?? mod.colours[0], scale: sc, style, crop });
  return { ...built, size, levels };
}

/** Size the canvas and draw `levels` onto it. */
export function paint(canvas, mod, levels, { colour, scale, style, crop }) {
  const { width, height } = canvasSize(mod, { scale, crop, colour });
  if (canvas.width !== width || canvas.height !== height) {
    canvas.width = width; canvas.height = height;
    canvas.style.width = `${width}px`; canvas.style.height = `${height}px`;
  }
  drawPanel(canvas.getContext('2d'), mod, levels, { colour, scale, style, crop });
  return { width, height };
}

export const designNames = () => Object.keys(DESIGNS);
